  /** The name for the new Figma file. */
  fileName: string,
  /**
   * The team or organization key (e.g. "team::1234567890" or "organization::1234567890"). Use the `key` field verbatim from one of the user's plans. If the user has more than one plan, ask which one to use before calling.
   * @minLength 1 @pattern ^(team|organization)::\d+$
   */
  planKey: string,
  /**
   * The type of Figma file to create. "design" creates a Figma design file. "figjam" creates a FigJam whiteboard file. "slides" creates a Figma Slides presentation file. "figspec" creates a standalone Figma spec. "figmake" creates an empty Figma Make file and returns its make_node_id; follow it with send_code_to_figma to import a project or send_prompt to generate an app, when those tools are available.
   */
  editorType: "design" | "figjam" | "slides" | "figspec" | "figmake",
  /**
   * The id of the project (folder) in Figma. If the URL is provided, extract the project id from the URL. Common URL formats include https://figma.com/files/project/:projectId, https://figma.com/files/:orgId/project/:projectId, and https://figma.com/files/team/:teamId/project/:projectId. The extracted projectId would be `:projectId`.
   */
  projectId?: string,
}): Promise<unknown>"},{"path":"tools.figma.create_generative_plugin","description":"You MUST load the figma-generative-plugins skill before calling this tool. If it is not installed, read skill://figma/figma-generative-plugins/SKILL.md with resources/read or get_figma_skill. Use this for requests to build, create, upload, or publish a “Figma plugin,” “generative plugin,” or “custom tool.” It creates a generative plugin in the account library; it does not install an existing Figma Community plugin. Creates a new generative plugin in the authenticated user's account library and returns its id. The plugin starts as a working scaffold — a runnable starter that draws a square — so it is a structural starting point, not a finished plugin: follow this call with the update tool to replace the scaffold's source with the behavior the user asked for. planKey names the plan that will own the plugin; take it from the plans list returned by whoami.","signature":"tools.figma.create_generative_plugin({
  /** Display name for the new resource. @minLength 1 */
  name: string,
  /** One-line description of what the resource does. @minLength 1 */
  description: string,
  /**
   * The team or organization key (e.g. "team::1234567890" or "organization::1234567890"). Use the `key` field verbatim from one of the user's plans. If the user has more than one plan, ask which one to use before calling.
   * @minLength 1 @pattern ^(team|organization)::\d+$
   */
  planKey: string,
}): Promise<unknown>"},{"path":"tools.figma.update_shader","description":"You MUST load the figma-shaders skill before calling this tool. If it is not installed, read skill://figma/figma-shaders/SKILL.md with resources/read or get_figma_skill. Use this when the user asks to update, revise, or republish an existing Figma shader, shader effect, shader fill, custom effect, custom fill, or procedural shader. Updates an existing shader effect or fill in the authenticated user's account library. Provide its id, matching kind, existing authored files to replace, optional name, description, animation, and mouse metadata, and a required Git commit message describing the change. The update is built, versioned, and deployed; the response includes the new version. Use create_shader first when no shader exists.","signature":"tools.figma.update_shader({
  /** The id of the existing resource to update. @minLength 1 */
  id: string,
  /** Existing main.ts to replace. New files cannot be created. @default [] @maxItems 5 */
  files?: Array<{
      /** The existing shader entrypoint path. */
      path: "main.ts",
      /** Complete replacement content for main.ts. @minLength 1 */
      content: string,
    }>,
  metadata?: {
    /** New display name for the shader. @minLength 1 */
    name?: string,
    /** New one-line description for the shader. @minLength 1 */
    description?: string,
    /** Whether the shader renders over time. */
    isAnimated?: boolean,
    /** Whether the shader reads the mouse position. */
    usesMouse?: boolean,
  },
  /**
   * A concise title capturing the user's requested goal or change. Describe the intent, not the implementation.
   * @minLength 1
   */
  commitMessage: string,
  /**
   * A single-line summary of the actual changes delivered in this version. Focus on the user-visible result.
   * @minLength 1
   */
  versionDescription?: string,
  /**
   * Adds the key implementation detail in 1–2 short sentences. Keep it proportional to the change; a small fix needs only one sentence. Do not repeat the outcome summary or list routine implementation steps. Include only details supported by the work performed.
   * @minLength 1
   */
  versionDetail?: string,
  /** The existing shader kind. It must match the resource identified by id. */
  kind: "effect" | "fill",
}): Promise<unknown>"}],"remaining":50,"next":{"offset":4}}

